    //              (state == 4'b0100) ? (in ? 4'b1000 : 4'b0001) :
    //              (state == 4'b1000) ? (in ? 4'b0010 : 4'b0100) : 4'b0000;

    // Implementing the above using Verilog case statement
    always @(*) begin
        case (state)
