    input  areset,
    input  j,
    input  k,
    output reg out
);

    // Define states
    localparam OFF = 2'b00;
    localparam ON  = 2'b01;

    // State register
    reg [1:0] current_state, next_state;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= OFF;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            OFF: begin
                if (j) next_state = ON;
                else next_state = OFF;
            end
            ON: begin
                if (k) next_state = OFF;
                else next_state = ON;
            end
            default: next_state = OFF;
        endcase
    end

    // Output logic (Moore machine: output depends only on state)
    always @(*) begin
        case (current_state)
            OFF: out = 1'b0;
            ON: out = 1'b1;
            default: out = 1'b0;
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  in,
    output out
);

typedef enum logic [1:0] {A, B, C, D} state_t;

state_t current_state, next_state;

always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
        current_state <= A;
    end else begin
        current_state <= next_state;
    end
end

always_comb begin
    next_state = current_state;
    out = 1'b0;

    case (current_state)
        A: begin
            next_state = (in == 1'b0) ? A : B;
            out = 1'b0;
        end
        B: begin
            next_state = (in == 1'b0) ? C : B;
            out = 1'b0;
        end
        C: begin
            next_state = (in == 1'b0) ? A : D;
            out = 1'b0;
        end
        D: begin
            next_state = (in == 1'b0) ? C : B;
            out = 1'b1;
        end
        default: begin
            next_state = A;
            out = 1'b0;
        end
    endcase
end

endmodule

