// Truth table for TopModule (simplified for state transition logic)
// Note: The actual logic is implemented in the module, not as a truth table.
// The truth table would be too large for a 256-bit state, so we describe the behavior instead.

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);

    // Internal register to hold the next state
    reg [255:0] next_q;

    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            q <= next_q;
        end
    end

    // Compute next state based on current state (q)
    always @(*) begin
        next_q = 256'h0;

        for (integer i = 0; i < 256; i = i + 1) begin
            // Get current cell value
            reg current_cell = q[i];

            // Count number of live neighbors
            integer neighbor_count = 0;

            // Check all 8 neighbors (toroidal grid)
            for (integer dx = -1; dx <= 1; dx = dx + 1) begin
                for (integer dy = -1; dy <= 1; dy = dy + 1) begin
                    if (dx == 0 && dy == 0) continue; // Skip current cell

                    integer x = (i / 16 + dx) % 16;
                    integer y = (i % 16 + dy) % 16;
                    integer neighbor_index = y * 16 + x;
                    neighbor_count += q[neighbor_index];
                end
            end

            // Apply Conway's Game of Life rules
            if (neighbor_count < 2 || neighbor_count > 3) begin
                next_q[i] = 1'b0;
            end else if (neighbor_count == 3) begin
                next_q[i] = 1'b1;
            end else begin
                next_q[i] = current_cell;
            end
        end
    end

endmodule

